import{_ as e,o as r,c as t,a2 as n}from"./chunks/framework.DfDAiEgj.js";const l="/2bPM/img/traditional_vs_AI_Investment_Research.png",f=JSON.parse('{"title":"智能投研","description":"","frontmatter":{},"headers":[],"relativePath":"ai-finance/AI_Investment_Research.md","filePath":"ai-finance/AI_Investment_Research.md","lastUpdated":null}'),o={name:"ai-finance/AI_Investment_Research.md"};function i(h,a,s,p,c,d){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="智能投研" tabindex="-1">智能投研 <a class="header-anchor" href="#智能投研" aria-label="Permalink to &quot;智能投研&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>在基础的金融数据基础上，通过深度学习、自然语音处理等等人工智能算法，对数据、时间和结论信息进行<strong>自动分析处理</strong>，为金融机构从业人员提供辅助，以提高行业工作效率。<a href="https://www.weiyangx.com/362573.html" target="_blank" rel="noreferrer">1</a></p><h2 id="需求" tabindex="-1">需求 <a class="header-anchor" href="#需求" aria-label="Permalink to &quot;需求&quot;">​</a></h2><p>随着互联网的普及，我们已身处信息爆炸时代，投研业务面临数据量过大、数据渠道过多、数据结构多样、数据真假难辨等突出问题，这些问题单靠传统的投研处理方法和手段已很难胜任或很难长期胜任，急需利器。</p><p>投研作为投资业务链条的一环，交易、风控等都在快速智能化发展，投研同样需要变革；保持分析的客观性是投研工作的基本要求，借助现代科技手段，既可以提高各类投研工作的效率，又可以<strong>弥补人类主观情绪</strong>的干扰。</p><p>投行业务及证券研究业务中涉及大量的固定格式的文档撰写工作，如招股说明书、研究报告及投资意向书等。这些报告的撰写需要初级研究员投入大量的时间及精力进行数据整理以及文本复制粘贴的工作。而这些文档中，有大量内容可以利用模板生成，比如公司股权变更、会计数据变更等等。<strong>利用自然语言处理及OCR技术</strong>可以方便快捷的完成以上工作，并最终形成文档。<a href="http://www.cstf.org.cn/newsdetail.asp?types=36&amp;num=1165" target="_blank" rel="noreferrer">6</a></p><h2 id="传统投研-vs-智能投研" tabindex="-1">传统投研 VS 智能投研 <a class="header-anchor" href="#传统投研-vs-智能投研" aria-label="Permalink to &quot;传统投研 VS 智能投研&quot;">​</a></h2><p><img src="'+l+'" alt="传统投研 VS 智能投研"></p><h2 id="基本流程" tabindex="-1">基本流程 <a class="header-anchor" href="#基本流程" aria-label="Permalink to &quot;基本流程&quot;">​</a></h2><ol><li>数据获取（金融数据、另类数据）</li><li>数据处理（结构化、模块化、建立联系）--模式化、标准化的工作</li><li>数据分析（建立公司、关键股东等动态知识图谱<a href="https://zhuanlan.zhihu.com/p/46750171" target="_blank" rel="noreferrer">3</a>）</li><li>观点输出（<strong>输出观点</strong>、分析结果）--<strong>核心价值</strong></li></ol><h2 id="智能投研-vs-智能投顾" tabindex="-1">智能投研 VS 智能投顾 <a class="header-anchor" href="#智能投研-vs-智能投顾" aria-label="Permalink to &quot;智能投研 VS 智能投顾&quot;">​</a></h2><ul><li>智能投顾主要是将人工智能辅助引入投顾业务。智能投顾更加偏向于站在客户立场上为客户提供资产配置建议，对客户资金配置到股票、债券、基金等品种上的份额提供合理建议，收取咨询服务费，主要面向C端客户</li><li>智能投研则是将人工智能引入投研业务中。智能投研更加偏向于辅助资产管理，服务于金融机构的投研人员，主要面向B端。</li></ul><h2 id="知识抽取" tabindex="-1">知识抽取 <a class="header-anchor" href="#知识抽取" aria-label="Permalink to &quot;知识抽取&quot;">​</a></h2><p>在金融领域，迅速、全面、准确地获取有价值的行业信息是决定一个企业成败的关键。近些年，随着互联网和金融行业的快速发展，每天都有大量的金融文本产生,面对着海量的公司年报、公告、新闻，其内容分散，数据稀疏，无结构化信息等特点逐渐凸显。如何在数据爆炸的信息中高效找到有价值的知识，将有价值的无结构化信息进行半结构化或结构化是首先需要解决的问题，而信息抽取则是知识发现的核心之一。</p><p>目前在金融领域中，<strong>文本内容的知识抽取</strong>主要依靠人工判断，分析人员一般需要阅读大量的相关文档(如：年报、公告、行业分析报告、新闻等)，然后从中获取关键信息，为决策提供依据。这种手工作业的方式效率较低，且依赖于从业人员的经验，学习门槛较高，不利于企业业务进一步拓展。<a href="https://www.zhihu.com/question/41187047/answer/1262911922" target="_blank" rel="noreferrer">4</a></p><p>CCKS 2020：面向金融领域的小样本跨类迁移事件抽取<a href="https://github.com/xiaoqian19940510/CCKS-2020-event-extraction" target="_blank" rel="noreferrer">7</a></p><h2 id="情绪分类" tabindex="-1">情绪分类 <a class="header-anchor" href="#情绪分类" aria-label="Permalink to &quot;情绪分类&quot;">​</a></h2><p>搜集大量财经新闻资讯透过NLP自然语言处理技术,分析文章针对原始文章萃取、摘要、并建立财经新闻情绪分类模型,用以分析特定行业与企业的正向、负向信息<a href="https://innovate.awssummit.cn/play.aspx?eid=7" target="_blank" rel="noreferrer">8</a></p><h2 id="智能投研产业链" tabindex="-1">智能投研产业链 <a class="header-anchor" href="#智能投研产业链" aria-label="Permalink to &quot;智能投研产业链&quot;">​</a></h2><p>上游数据源与数据采集、中游数据处理、下游为各类用户。</p><p>TODO:<a href="https://www.weiyangx.com/362573.html" target="_blank" rel="noreferrer">1</a></p><h2 id="不是替代-而是辅助" tabindex="-1">不是替代，而是辅助 <a class="header-anchor" href="#不是替代-而是辅助" aria-label="Permalink to &quot;不是替代，而是辅助&quot;">​</a></h2><p>智能投研不是替代投研人员，更无法替代资深的投研人员。毕竟很多信息还需要现场调研获取和确认，分析模型、逻辑也需要逐步完善，服务于基金经理、交易员的有灵魂的报告还离不开人去加工润色。如果非要说替代，那替代的首先是价值含量低的工作，比如当前很多公司临时聘用实习生来做的数据采集、处理、分析等工作；其次是那些没有掌握智能投研利器的从业人员。</p><p>智能投研在可预见的将来仍将以做辅助工作为主，投研的核心是<strong>优秀的投研人员输出观点</strong>，根据有效市场理论，正是因为不同投研人员的预期不同，所以才能为客户赚取超额收益，从而跑赢市场。</p><h2 id="相关企业" tabindex="-1">相关企业 <a class="header-anchor" href="#相关企业" aria-label="Permalink to &quot;相关企业&quot;">​</a></h2><p>国内外的初创企业也是非常重要的推动力量,比如 AlphaSense推出的智能擭索引擎,使用自然语言处理技术来提取对投资可能产生影响的关键信息。</p><p>国内比如文因互联强化自身深度语义分析和深度文档分析能力的技术优势,过自然语言处理和知识图谱,来对金融数据进行结构化地提取和分析;阿博茨与汇添富基金合作,为汇添富提供智能投研系统,通过应用知识图谱、大数据和A算法,针对投硏数据进行搜索定位从而提高信息阅读效率,辅助投研。此外比如通联数据的萝卜投研、香侬科技熵简科技等也在智能投研方面有相应布局<a href="http://www.199it.com/archives/1223002.html" target="_blank" rel="noreferrer">5</a></p><h2 id="更多" tabindex="-1">更多 <a class="header-anchor" href="#更多" aria-label="Permalink to &quot;更多&quot;">​</a></h2><p><a href="http://gb.oversea.cnki.net/KCMS/detail/detail.aspx?filename=1020099658.nh&amp;dbcode=CMFD&amp;dbname=CMFDREF" target="_blank" rel="noreferrer">http://gb.oversea.cnki.net/KCMS/detail/detail.aspx?filename=1020099658.nh&amp;dbcode=CMFD&amp;dbname=CMFDREF</a></p>',30)])])}const _=e(o,[["render",i]]);export{f as __pageData,_ as default};
